mapper.update:
update "interviewworks_schema"."userdata_details"
set is_active  = '1', is_active_notifications =  '1'
where username = #{username}

mapper.select:
select distinct quotations.quotation_id, quotations.status, userdata_details.username, quotations.total_price from "interviewworks_schema"."userdata_details" userdata_details inner join "interviewworks_schema"."quotations" quotations on userdata_details.username = quotations.username inner join "interviewworks_schema"."quotation_items" quotation_items on quotations.quotation_id = quotation_items.quotation_id
and userdata_details.is_active = '1' and userdata_details.username = #{username}
and quotations.status in
#{status}
order by quotations.quotation_id

select quotations.quotation_id, quotations.status, userdata_details.username, quotation_items.quantity, quotation_items.price, quotation_items.quantity * quotation_items.price as sum_price, products.products_name, products.description from "interviewworks_schema"."userdata_details" userdata_details inner join "interviewworks_schema"."quotations" quotations on userdata_details.username = quotations.username inner join "interviewworks_schema"."quotation_items" quotation_items on quotations.quotation_id = quotation_items.quotation_id inner join "interviewworks_schema"."products" products on quotation_items.product_id = products.product_id
and userdata_details.is_active = '1'
and quotations.quotation_id = #{quotation_id}
and userdata_details.tracking_number is null and userdata_details.username = #{username}
and quotations.status in
#{status}
order by quotations.quotation_id

mapper.update:
update "interviewworks_schema"."quotations"
set status = #{status}
where username = #{username}
  and quotation_id = #{quotation_id}
